package recoveryexport

// Exact PostgreSQL16 definitions of db/generation_postgres.sql.
var generationConstraints = map[identityConstraintKey]identityConstraintSpec{
	{"capture_generation", "capture_generation_check"}:                                     {"c", "CHECK (((ended_ns IS NULL) OR ((started_ns IS NOT NULL) AND (ended_ns >= started_ns))))"},
	{"capture_generation", "capture_generation_ended_ns_check"}:                            {"c", "CHECK ((ended_ns >= 0))"},
	{"capture_generation", "capture_generation_generation_id_check"}:                       {"c", "CHECK ((generation_id ~ '^generation_[0-9a-f]{32}$'::text))"},
	{"capture_generation", "capture_generation_outcome_check"}:                             {"c", "CHECK ((outcome = ANY (ARRAY['unknown'::text, 'incomplete'::text, 'failed'::text])))"},
	{"capture_generation", "capture_generation_pkey"}:                                      {"p", "PRIMARY KEY (generation_id)"},
	{"capture_generation", "capture_generation_publication_receipt_check"}:                 {"c", "CHECK ((publication_receipt IS NULL))"},
	{"capture_generation", "capture_generation_repository_id_fkey"}:                        {"f", "FOREIGN KEY (repository_id) REFERENCES repository_identity(repository_id)"},
	{"capture_generation", "capture_generation_scan_state_check"}:                          {"c", "CHECK ((scan_state = ANY (ARRAY['unknown'::text, 'pending'::text, 'partial'::text, 'enumerated'::text])))"},
	{"capture_generation", "capture_generation_source_id_policy_id_policy_sha256_fkey"}:    {"f", "FOREIGN KEY (source_id, policy_id, policy_sha256) REFERENCES generation_policy(source_id, policy_id, descriptor_sha256)"},
	{"capture_generation", "capture_generation_source_id_source_revision_fkey"}:            {"f", "FOREIGN KEY (source_id, source_revision) REFERENCES source_binding_revision(source_id, revision)"},
	{"capture_generation", "capture_generation_started_ns_check"}:                          {"c", "CHECK ((started_ns >= 0))"},
	{"generation_entry", "generation_entry_check"}:                                         {"c", "CHECK (((logical_file_id IS NOT NULL) = ((kind = 'file'::text) AND (outcome = 'stored'::text))))"},
	{"generation_entry", "generation_entry_component_check"}:                               {"c", "CHECK (((octet_length(component) >= 1) AND (octet_length(component) <= 255)))"},
	{"generation_entry", "generation_entry_component_check1"}:                              {"c", "CHECK ((POSITION((decode('00'::text, 'hex'::text)) IN (component)) = 0))"},
	{"generation_entry", "generation_entry_component_check2"}:                              {"c", "CHECK ((POSITION((decode('2f'::text, 'hex'::text)) IN (component)) = 0))"},
	{"generation_entry", "generation_entry_component_check3"}:                              {"c", "CHECK ((component <> ALL (ARRAY[decode('2e'::text, 'hex'::text), decode('2e2e'::text, 'hex'::text)])))"},
	{"generation_entry", "generation_entry_entry_id_check"}:                                {"c", "CHECK ((entry_id ~ '^entry_[0-9a-f]{32}$'::text))"},
	{"generation_entry", "generation_entry_generation_id_entry_id_kind_key"}:               {"u", "UNIQUE (generation_id, entry_id, kind)"},
	{"generation_entry", "generation_entry_generation_id_fkey"}:                            {"f", "FOREIGN KEY (generation_id) REFERENCES capture_generation(generation_id)"},
	{"generation_entry", "generation_entry_generation_id_parent_id_component_key"}:         {"u", "UNIQUE NULLS NOT DISTINCT (generation_id, parent_id, component)"},
	{"generation_entry", "generation_entry_generation_id_parent_id_parent_kind_fkey"}:      {"f", "FOREIGN KEY (generation_id, parent_id, parent_kind) REFERENCES generation_entry(generation_id, entry_id, kind)"},
	{"generation_entry", "generation_entry_kind_check"}:                                    {"c", "CHECK ((kind = ANY (ARRAY['file'::text, 'directory'::text])))"},
	{"generation_entry", "generation_entry_logical_file_id_fkey"}:                          {"f", "FOREIGN KEY (logical_file_id) REFERENCES logical_file(id)"},
	{"generation_entry", "generation_entry_mode_check"}:                                    {"c", "CHECK (((mode >= 0) AND (mode <= 4095)))"},
	{"generation_entry", "generation_entry_outcome_check"}:                                 {"c", "CHECK ((outcome = ANY (ARRAY['stored'::text, 'excluded'::text, 'missing'::text, 'unreadable'::text, 'unstable'::text, 'unsupported'::text])))"},
	{"generation_entry", "generation_entry_parent_kind_check"}:                             {"c", "CHECK ((parent_kind = 'directory'::text))"},
	{"generation_entry", "generation_entry_pkey"}:                                          {"p", "PRIMARY KEY (generation_id, entry_id)"},
	{"generation_policy", "generation_policy_check"}:                                       {"c", "CHECK ((descriptor_sha256 = encode(sha256(descriptor), 'hex'::text)))"},
	{"generation_policy", "generation_policy_descriptor_check"}:                            {"c", "CHECK (((octet_length(descriptor) >= 2) AND (octet_length(descriptor) <= 4096)))"},
	{"generation_policy", "generation_policy_pkey"}:                                        {"p", "PRIMARY KEY (policy_id)"},
	{"generation_policy", "generation_policy_policy_id_check"}:                             {"c", "CHECK ((policy_id ~ '^policy_[0-9a-f]{32}$'::text))"},
	{"generation_policy", "generation_policy_repository_id_fkey"}:                          {"f", "FOREIGN KEY (repository_id) REFERENCES repository_identity(repository_id)"},
	{"generation_policy", "generation_policy_source_id_fkey"}:                              {"f", "FOREIGN KEY (source_id) REFERENCES configured_source(source_id)"},
	{"generation_policy", "generation_policy_source_id_policy_id_descriptor_sha256_key"}:   {"u", "UNIQUE (source_id, policy_id, descriptor_sha256)"},
	{"generation_root", "generation_root_generation_id_fkey"}:                              {"f", "FOREIGN KEY (generation_id) REFERENCES capture_generation(generation_id)"},
	{"generation_root", "generation_root_mode_check"}:                                      {"c", "CHECK (((mode >= 0) AND (mode <= 4095)))"},
	{"generation_root", "generation_root_pkey"}:                                            {"p", "PRIMARY KEY (generation_id)"},
	{"schema_upgrade_operation", "schema_upgrade_operation_from_version_check"}:            {"c", "CHECK ((from_version = 19))"},
	{"schema_upgrade_operation", "schema_upgrade_operation_generation_check"}:              {"c", "CHECK ((generation ~ '^[0-9a-f]{32}$'::text))"},
	{"schema_upgrade_operation", "schema_upgrade_operation_manifest_sha256_check"}:         {"c", "CHECK ((manifest_sha256 ~ '^[0-9a-f]{64}$'::text))"},
	{"schema_upgrade_operation", "schema_upgrade_operation_operation_id_check"}:            {"c", "CHECK ((operation_id ~ '^upgrade_[0-9a-f]{32}$'::text))"},
	{"schema_upgrade_operation", "schema_upgrade_operation_operation_id_key"}:              {"u", "UNIQUE (operation_id)"},
	{"schema_upgrade_operation", "schema_upgrade_operation_pkey"}:                          {"p", "PRIMARY KEY (singleton)"},
	{"schema_upgrade_operation", "schema_upgrade_operation_plan_sha256_check"}:             {"c", "CHECK ((plan_sha256 ~ '^[0-9a-f]{64}$'::text))"},
	{"schema_upgrade_operation", "schema_upgrade_operation_prior_plan_check"}:              {"c", "CHECK ((prior_plan ~ '^[0-9a-f]{64}$'::text))"},
	{"schema_upgrade_operation", "schema_upgrade_operation_repository_id_fkey"}:            {"f", "FOREIGN KEY (repository_id) REFERENCES repository_identity(repository_id)"},
	{"schema_upgrade_operation", "schema_upgrade_operation_request_sha256_check"}:          {"c", "CHECK ((request_sha256 ~ '^[0-9a-f]{64}$'::text))"},
	{"schema_upgrade_operation", "schema_upgrade_operation_root_id_binding_revision_fkey"}: {"f", "FOREIGN KEY (root_id, binding_revision) REFERENCES root_binding_revision(root_id, revision)"},
	{"schema_upgrade_operation", "schema_upgrade_operation_root_id_fkey"}:                  {"f", "FOREIGN KEY (root_id) REFERENCES storage_root_identity(root_id)"},
	{"schema_upgrade_operation", "schema_upgrade_operation_singleton_check"}:               {"c", "CHECK ((singleton = 1))"},
	{"schema_upgrade_operation", "schema_upgrade_operation_to_version_check"}:              {"c", "CHECK ((to_version = 20))"},
}
